const $=s=>document.querySelector(s);let access='',url='',anon='',data={appointments:[],therapists:[]};const fmt=x=>new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',hour:'numeric',minute:'2-digit'}).format(new Date(x));const text=(tag,value)=>{let e=document.createElement(tag);e.textContent=value;return e};async function call(body){let r=await fetch('/.netlify/functions/api',{method:'POST',headers:{'Content-Type':'application/json',...(access?{Authorization:`Bearer ${access}`}:{})},body:JSON.stringify(body)});let d=await r.json();if(!r.ok)throw Error(d.error);return d}function status(s){$('#status').textContent=s}function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}$('#day').value=today();async function load(){try{const selected=$('#day').value,weekStart=monday(selected),results=await Promise.all([call({action:'staffList',date:selected}),call({action:'staffWeek',date:weekStart})]);if(selected!==$('#day').value)return;data=results[0];renderWeek(weekStart,results[1].appointments,selected);$('#invite-section').hidden=data.role!=='admin';const booked=data.appointments.filter(a=>a.status==='booked');$('#summary').textContent=`${booked.length} bookings · ${data.appointments.length-booked.length} cancellations · ₱${booked.reduce((n,a)=>n+a.price,0).toLocaleString()} booked service value · ₱${data.appointments.reduce((n,a)=>n+Number(a.payment_recorded),0).toLocaleString()} staff-recorded payments`;renderCalendar(data.appointments);const container=$('#appointments');container.replaceChildren();for(const a of data.appointments){const section=document.createElement('section');section.append(text('h3',`${fmt(a.start_at)}–${fmt(a.end_at)} · ${a.room_id} · ${a.service} · ${a.status==='cancelled'?'cancelled':Date.now()<Date.parse(a.start_at)?'upcoming':Date.now()<Date.parse(a.end_at)?'active session':Date.now()<Date.parse(a.end_at)+1800000?'cleaning':'completed'}`),text('p',`${a.reference} · ${a.customer_name} · ${a.customer_email} · ${a.guests} guests · ₱${a.price} · receipt ${a.receipt_status}${a.late_review?' · late change flagged':''}`),text('p',`Health declaration: ${a.health_yes?'Yes — '+a.health_details:'No'} · cleaning until ${fmt(new Date(Date.parse(a.end_at)+1800000))}`));const assign=document.createElement('select');assign.add(new Option('No therapist',''));data.therapists.filter(t=>t.active).forEach(t=>assign.add(new Option(t.name,t.id)));assign.value=a.therapist_id||'';assign.onchange=()=>update({id:a.id,therapistId:assign.value||null});const receipt=document.createElement('select');['pending','reviewed','rejected'].forEach(x=>receipt.add(new Option(x,x)));receipt.value=a.receipt_status;receipt.onchange=()=>update({id:a.id,receiptStatus:receipt.value});const receiptButton=text('button','Prepare receipt link'),receiptLink=text('a','Open receipt (link expires in 60 seconds)');receiptLink.hidden=true;receiptLink.target='_blank';receiptLink.rel='noopener noreferrer';receiptButton.onclick=async()=>{try{const d=await call({action:'receipt',id:a.id});receiptLink.href=d.url;receiptLink.hidden=false;status('Receipt link is ready for 60 seconds.')}catch(e){status(e.message)}};const pay=document.createElement('input');pay.type='number';pay.min='0';pay.step='.01';pay.value=a.payment_recorded;pay.setAttribute('aria-label','Staff-recorded payment amount');const save=text('button','Record amount');save.onclick=()=>update({id:a.id,payment:Number(pay.value)});section.append(text('p','Therapist assignment'),assign,text('p','Receipt review (not automatic payment verification)'),receipt,receiptButton,receiptLink,text('p','Payment amount recorded by staff'),pay,save);container.append(section)}$('#therapist-list').replaceChildren(...data.therapists.map(t=>{const row=document.createElement('p');row.append(text('span',`${t.name} (${t.active?'active':'inactive'}): ${booked.filter(a=>a.therapist_id===t.id).map(a=>`${fmt(a.start_at)} ${a.room_id}`).join(', ')||'No assignments'} `));const toggle=text('button',t.active?'Deactivate':'Reactivate');toggle.onclick=async()=>{try{await call({action:'therapistUpdate',id:t.id,active:!t.active});await load()}catch(e){status(e.message)}};row.append(toggle);return row}));status('Schedule loaded.')}catch(e){status(e.message)}}async function update(payload){try{await call({action:'staffUpdate',...payload});await load()}catch(e){status(e.message);await load();status(e.message)}}$('#login').onsubmit=async e=>{e.preventDefault();try{const config=await call({action:'config'});url=config.url;anon=config.anon;const r=await fetch(url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:anon,'Content-Type':'application/json'},body:JSON.stringify({email:$('#email').value,password:$('#password').value})});const d=await r.json();if(!r.ok)throw Error('Sign-in failed.');access=d.access_token;$('#password').value='';$('#login').hidden=true;$('#dashboard').hidden=false;await load()}catch(err){status(err.message)}};$('#logout').onclick=()=>{access='';$('#dashboard').hidden=true;$('#login').hidden=false;status('Signed out.')};$('#refresh').onclick=load;$('#day').onchange=load;$('#therapist-form').onsubmit=async e=>{e.preventDefault();try{await call({action:'therapist',name:$('#therapist-name').value});$('#therapist-name').value='';await load()}catch(err){status(err.message)}};$('#invite-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button'),notice=$('#invite-status');button.disabled=true;notice.textContent='Sending invitation…';try{await call({action:'invite',email:$('#invite-email').value,role:$('#invite-role').value});notice.textContent='Invitation sent. Ask the staff member to check their email and spam folder.';$('#invite-email').value=''}catch(err){notice.textContent=err.message||'Could not confirm the invitation. Check Supabase before trying again.'}finally{button.disabled=false}};

const inviteParams=new URLSearchParams(location.hash.slice(1));if(inviteParams.get('access_token')){access=inviteParams.get('access_token');history.replaceState(null,'',location.pathname);$('#login').hidden=true;$('#set-password').hidden=false}$('#set-password').onsubmit=async e=>{e.preventDefault();try{const config=await call({action:'config'});url=config.url;anon=config.anon;const response=await fetch(url+'/auth/v1/user',{method:'PUT',headers:{apikey:anon,Authorization:`Bearer ${access}`,'Content-Type':'application/json'},body:JSON.stringify({password:$('#new-password').value})});if(!response.ok)throw Error('Unable to set password; the invitation may have expired.');$('#new-password').value='';$('#set-password').hidden=true;$('#dashboard').hidden=false;await load()}catch(err){status(err.message)}};setInterval(()=>{if(access&&!$('#dashboard').hidden&&!document.hidden&&!$('#dashboard').contains(document.activeElement))load()},10000);

function renderCalendar(appointments){const holder=$('#calendar'),table=document.createElement('table'),head=document.createElement('tr');head.append(text('th','Room'));for(let m=780;m<=1260;m+=30){const h=Math.floor(m/60);head.append(text('th',`${h%12||12}:${String(m%60).padStart(2,'0')}`))}table.append(head);for(const room of ['SR-1','SR-2','SR-3','CS-1','CS-2','FL-1','FL-2']){const row=document.createElement('tr');row.append(text('th',room));for(let m=780;m<=1260;m+=30){const slot=Date.parse(`${$('#day').value}T${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}:00+08:00`),a=appointments.find(x=>x.status==='booked'&&x.room_id===room&&Date.parse(x.start_at)<slot+1800000&&Date.parse(x.end_at)+1800000>slot),cell=document.createElement('td');if(a){const cleaning=slot>=Date.parse(a.end_at);cell.className=cleaning?'calendar-cleaning':'calendar-booked';cell.textContent=cleaning?'Clean':'Booked';cell.title=`${a.reference}: ${cleaning?'cleaning':'treatment'}`}else cell.textContent='—';row.append(cell)}table.append(row)}holder.replaceChildren(table)}

function shiftDate(date,days){const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}function monday(date){const d=new Date(date+'T00:00:00Z');return shiftDate(date,-((d.getUTCDay()+6)%7))}function localDay(value){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value))}function prettyDay(date){return new Intl.DateTimeFormat('en-PH',{timeZone:'UTC',weekday:'short',month:'short',day:'numeric'}).format(new Date(date+'T00:00:00Z'))}function renderWeek(start,appointments,selected){const container=$('#week-calendar');container.replaceChildren();$('#week-label').textContent=`${prettyDay(start)} – ${prettyDay(shiftDate(start,6))}`;for(let i=0;i<7;i++){const day=shiftDate(start,i),card=document.createElement('article'),button=text('button',prettyDay(day));button.type='button';button.className='week-day-button';if(day===selected)button.setAttribute('aria-current','date');button.onclick=()=>{$('#day').value=day;$('#day').focus();load()};card.append(button);const entries=appointments.filter(a=>localDay(a.start_at)===day);if(!entries.length)card.append(text('p','No appointments'));else entries.forEach(a=>card.append(text('p',`${fmt(a.start_at)} · ${a.room_id} · ${a.service} · ${a.status==='cancelled'?'cancelled':'booked'} · ${a.reference}`)));container.append(card)}}$('#prev-week').onclick=()=>{$('#day').value=shiftDate(monday($('#day').value),-7);load()};$('#next-week').onclick=()=>{$('#day').value=shiftDate(monday($('#day').value),7);load()};$('#current-week').onclick=()=>{$('#day').value=today();load()};
